import { Component } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '../../services/auth.service';

@Component({
  selector: 'app-register',
  templateUrl: './register.component.html',
  styleUrls: ['./register.component.css']
})
export class RegisterComponent {
  registerForm: FormGroup;
  isLoading = false;
  errorMessage = '';
  successMessage = '';

  constructor(
    private fb: FormBuilder,
    private authService: AuthService,
    private router: Router
  ) {
    this.registerForm = this.fb.group({
      firstName: ['', [Validators.required, Validators.maxLength(100)]],
      lastName: ['', [Validators.required, Validators.maxLength(100)]],
      email: ['', [Validators.required, Validators.email]],
      password: ['', [Validators.required, Validators.minLength(6)]],
      phone: ['', [Validators.maxLength(11)]]
    });
  }

  onSubmit(): void {
    if (this.registerForm.invalid) {
      this.markFormGroupTouched(this.registerForm);
      return;
    }

    this.isLoading = true;
    this.errorMessage = '';
    this.successMessage = '';

    const registerData = this.registerForm.value;

    this.authService.register(registerData).subscribe({
      next: (response) => {
        if (response.success) {
          this.successMessage = response.message || 'Đăng ký thành công!';
          setTimeout(() => {
            this.router.navigate(['/login']);
          }, 2000);
        } else {
          this.errorMessage = response.message || 'Đăng ký thất bại';
          this.isLoading = false;
        }
      },
      error: (error) => {
        this.errorMessage = error.error?.message || 'Đăng ký thất bại. Vui lòng thử lại!';
        this.isLoading = false;
      }
    });
  }

  private markFormGroupTouched(formGroup: FormGroup): void {
    Object.keys(formGroup.controls).forEach(key => {
      const control = formGroup.get(key);
      control?.markAsTouched();
    });
  }

  get firstName() {
    return this.registerForm.get('firstName');
  }

  get lastName() {
    return this.registerForm.get('lastName');
  }

  get email() {
    return this.registerForm.get('email');
  }

  get password() {
    return this.registerForm.get('password');
  }

  get phone() {
    return this.registerForm.get('phone');
  }
}
<div class="register-container">
  <div class="register-card">
    <div class="register-header">
      <h1>Đăng Ký</h1>
      <p>Tạo tài khoản mới để bắt đầu</p>
    </div>

    <form [formGroup]="registerForm" (ngSubmit)="onSubmit()">
      <div *ngIf="errorMessage" class="alert alert-error">
        {{ errorMessage }}
      </div>

      <div *ngIf="successMessage" class="alert alert-success">
        {{ successMessage }}
      </div>

      <div class="form-row">
        <div class="form-group">
          <label class="form-label" for="firstName">Tên</label>
          <input
            type="text"
            id="firstName"
            class="form-control"
            formControlName="firstName"
            placeholder="Nhập tên của bạn"
            [class.error]="firstName?.invalid && firstName?.touched"
          />
          <div *ngIf="firstName?.invalid && firstName?.touched" class="error-message">
            <span *ngIf="firstName?.errors?.['required']">Tên không được để trống</span>
            <span *ngIf="firstName?.errors?.['maxlength']">Tên không được vượt quá 100 ký tự</span>
          </div>
        </div>

        <div class="form-group">
          <label class="form-label" for="lastName">Họ</label>
          <input
            type="text"
            id="lastName"
            class="form-control"
            formControlName="lastName"
            placeholder="Nhập họ của bạn"
            [class.error]="lastName?.invalid && lastName?.touched"
          />
          <div *ngIf="lastName?.invalid && lastName?.touched" class="error-message">
            <span *ngIf="lastName?.errors?.['required']">Họ không được để trống</span>
            <span *ngIf="lastName?.errors?.['maxlength']">Họ không được vượt quá 100 ký tự</span>
          </div>
        </div>
      </div>

      <div class="form-group">
        <label class="form-label" for="email">Email</label>
        <input
          type="email"
          id="email"
          class="form-control"
          formControlName="email"
          placeholder="Nhập email của bạn"
          [class.error]="email?.invalid && email?.touched"
        />
        <div *ngIf="email?.invalid && email?.touched" class="error-message">
          <span *ngIf="email?.errors?.['required']">Email không được để trống</span>
          <span *ngIf="email?.errors?.['email']">Email không đúng định dạng</span>
        </div>
      </div>

      <div class="form-group">
        <label class="form-label" for="password">Mật khẩu</label>
        <input
          type="password"
          id="password"
          class="form-control"
          formControlName="password"
          placeholder="Nhập mật khẩu (tối thiểu 6 ký tự)"
          [class.error]="password?.invalid && password?.touched"
        />
        <div *ngIf="password?.invalid && password?.touched" class="error-message">
          <span *ngIf="password?.errors?.['required']">Mật khẩu không được để trống</span>
          <span *ngIf="password?.errors?.['minlength']">Mật khẩu phải có ít nhất 6 ký tự</span>
        </div>
      </div>

      <div class="form-group">
        <label class="form-label" for="phone">Số điện thoại (tùy chọn)</label>
        <input
          type="tel"
          id="phone"
          class="form-control"
          formControlName="phone"
          placeholder="Nhập số điện thoại"
          [class.error]="phone?.invalid && phone?.touched"
        />
        <div *ngIf="phone?.invalid && phone?.touched" class="error-message">
          Số điện thoại không được vượt quá 11 ký tự
        </div>
      </div>

      <div class="form-group">
        <button
          type="submit"
          class="btn btn-primary btn-block"
          [disabled]="isLoading"
        >
          <span *ngIf="!isLoading">Đăng Ký</span>
          <span *ngIf="isLoading">
            <span class="loading"></span> Đang đăng ký...
          </span>
        </button>
      </div>

      <div class="form-footer">
        <p class="login-link">
          Đã có tài khoản? <a routerLink="/login">Đăng nhập ngay</a>
        </p>
      </div>
    </form>
  </div>
</div>
